use super::*;
use crate::org::apache::poi::ss::{SpreadsheetVersion::{SpreadsheetVersion,CUR_VERSION},util::CellRangeAddressBase::CellRangeAddressBase};
use serde_json::{Value,json};
use std::panic::{catch_unwind,AssertUnwindSafe};
fn call<T:serde::Serialize>(f:impl FnOnce()->T)->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(v)=>json!({"result":"ok","value":v}),Err(e)=>{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");let n=["NullPointerException","IllegalArgumentException","RuntimeException","ArrayIndexOutOfBoundsException"].into_iter().find(|n|s.starts_with(n)).unwrap_or(s);json!({"result":n})}}}
fn bytes(s:&str)->Vec<u8>{(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect()}
fn refs(p:&Value)->Value{let sv=if p["version"]==97{SpreadsheetVersion::EXCEL97}else{SpreadsheetVersion::EXCEL2007};*CUR_VERSION.lock().unwrap()=sv;let b=bytes(p["bytes"].as_str().unwrap());let token=Ptg::readTokens__stream(b.len()as i32,&b,false,sv).remove(0);let reference=matches!(token.kind,PtgKind::Ref{..}|PtgKind::Ref3D{..});let a1=call(||if reference{token.formatReferenceAsString()}else{token.formatAreaReferenceAsString()});let mut rc=vec![];for n in 0..4{let f=if n==0{None}else{Some(CellRangeAddressBase::CellRangeAddressBase(if n==1{0}else if n==2{4}else{i32::MIN},9,if n==1{0}else if n==2{5}else{i32::MAX},12))};let o=if n==0{None}else{Some(CellRangeAddressBase::CellRangeAddressBase(if n==1{0}else if n==2{2}else{i32::MAX},9,if n==1{0}else if n==2{3}else{i32::MIN},12))};for name in[false,true]{rc.push(call(||if reference{token.formatRCReferenceAsString(f.as_ref(),o.as_ref(),sv,name)}else{token.formatAreaRCReferenceAsString(f.as_ref(),o.as_ref(),sv,name)}));}}json!({"a1":a1,"rc":rc})}
fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}
#[test]
fn original_android_ptg_reference_and_operator_formatting(){let p=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("rewrite-review/milestones/m4-edit-save/evidence/ptg-format-r0b55");let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let rs:Vec<_>=input["refs"].as_array().unwrap().iter().map(refs).collect();*CUR_VERSION.lock().unwrap()=SpreadsheetVersion::EXCEL2007;let mut ops=vec![];for k in[PtgKind::Add,PtgKind::Subtract,PtgKind::Multiply,PtgKind::Divide,PtgKind::Power,PtgKind::Concat,PtgKind::Equal,PtgKind::LessThan,PtgKind::GreaterThan,PtgKind::LessEqual,PtgKind::GreaterEqual,PtgKind::NotEqual,PtgKind::UnaryMinus,PtgKind::UnaryPlus,PtgKind::Percent,PtgKind::Union,PtgKind::Intersection,PtgKind::Range]{let op=Ptg::base(k);ops.push(json!({"count":op.operatorOperandCount(),"cases":input["ops"].as_array().unwrap().iter().map(|p|{let operands=p["operands"].as_array().map(|a|a.iter().map(|s|s.as_str().map(str::to_string)).collect::<Vec<_>>());call(||op.operatorFormulaString(operands.as_deref(),char::from_u32(p["arg"].as_u64().unwrap()as u32).unwrap(),char::from_u32(p["union"].as_u64().unwrap()as u32).unwrap()))}).collect::<Vec<_>>()}));}let actual=json!({"refs":rs,"ops":ops});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();compare(&actual,&java,"root");}
